{% csrf_token %}
{# PREBOOK_UPGRADE_20261103: draft only, no automatic sale or payment. #}
{% if prebooking_prefill %}
<input type="hidden" name="prebooking_id" value="{{ prebooking_prefill.id }}">
{{ prebooking_prefill|json_script:"prebookingSalePrefillData" }}
<div id="prebookingDraftNotice" role="status" style="padding:14px 16px;margin:10px 0;border:1px solid #b6d8ed;border-radius:12px;background:#eff8ff;color:#164d72;font-size:12px;line-height:1.6">
  <strong>Draft from {{ prebooking_prefill.booking_number }} · {{ prebooking_prefill.channel }}</strong><br>
  Check customer, quantities, rates and sellable stock. This pre-booking has NOT created an invoice. Payment defaults to <strong>Full Credit (unpaid)</strong> until you deliberately choose otherwise.
  <div id="prebookingStockNotice" style="font-weight:bold;color:#aa3b1e" hidden></div>
  <label style="display:flex;align-items:center;gap:8px;margin-top:8px;font-weight:700"><input type="checkbox" name="confirm_payment_received" value="yes"> I personally verified the payment was actually received (tick ONLY for Paid in Full / Partial).</label>
</div>
{% endif %}

// PREBOOK_UPGRADE_20261103: Fill the existing POS cart from a validated booking.
// No invoices/payments are created until user presses Complete Sale.
function loadConfirmedPrebooking() {
    const dataElement = document.getElementById("prebookingSalePrefillData");
    if (!dataElement) return;
    const data = JSON.parse(dataElement.textContent);
    const credit = document.querySelector('input[name="payment_type"][value="credit"]');
    if (credit) { credit.checked = true; updatePaymentUI(); }
    if (data.customer_id) {
        customerSelect.value = String(data.customer_id);
        refreshCustomerInfo();
    } else {
        openNewCustomerModal();
        newCustomerForm.querySelector('[name="name"]').value = data.customer_name || "";
        newCustomerForm.querySelector('[name="phone"]').value = data.customer_phone || "";
        newCustomerForm.querySelector('[name="address"]').value = data.delivery_area || "";
    }
    const note = document.querySelector('#saleForm textarea[name="notes"]');
    if (note && !note.value) note.value = (data.notes || "").slice(0, 1200);
    const shortages = [];
    // Validate the WHOLE booking first. Do not silently show a smaller cart.
    for (const item of data.items || []) {
        const card = Array.from(productList.querySelectorAll('[data-product-card]')).find(
            node => Number(node.dataset.productId) === Number(item.product_id)
        );
        if (!card || Number(card.dataset.stock || 0) < Number(item.eggs || 0)) {
            shortages.push((card?.dataset.name || 'Egg product #' + item.product_id) +
                ' needs ' + item.eggs + ' eggs, available ' + (card?.dataset.stock || 0));
        }
    }
    if (shortages.length) {
        const warning = document.getElementById("prebookingStockNotice");
        if (warning) {
            warning.hidden = false;
            warning.textContent = "Not enough sellable stock to prefill this booking. " + shortages.join("; ") +
              ". Enter stock before invoicing; no partial cart was created.";
        }
        return;
    }
    for (const item of data.items || []) {
        const card = Array.from(productList.querySelectorAll('[data-product-card]')).find(
            node => Number(node.dataset.productId) === Number(item.product_id)
        );
        if (!card) continue;
        addProduct(card);
        const row = getCartItem(item.product_id);
        if (!row) continue;
        const unit = Object.prototype.hasOwnProperty.call(SALE_UNITS, item.unit) ? item.unit : 'egg';
        if (unit !== 'egg') setSaleUnit(row, unit);
        row.querySelector('.cart-qty').value = String(item.unit_count);
        calculate();
    }
    updatePaymentUI();
}

refreshCustomerInfo();
updatePaymentUI();
calculate();
loadConfirmedPrebooking();
